const STRICT_FAMILY = [
  'alwaysStrict', 'noImplicitAny', 'noImplicitThis', 'strictBindCallApply',
  'strictBuiltinIteratorReturn', 'strictFunctionTypes', 'strictNullChecks',
  'strictPropertyInitialization', 'useUnknownInCatchVariables',
];

function strictFlags(options: Record<string, boolean>): string[] {
  const base = options.strict === true;
  return STRICT_FAMILY.filter(flag => {
    const own = Object.prototype.hasOwnProperty.call(options, flag) ? options[flag] : undefined;
    return own ?? base;
  }).sort();
}

