function lookup(record: Record<string, number>, key: string, fallback: number): number {
  if (!Object.prototype.hasOwnProperty.call(record, key)) return fallback;
  const value: number | undefined = record[key];
  return value ?? fallback;
}

type Decl = { name: string; members: Record<string, string> };

function mergeInterfaces(decls: Decl[]): Record<string, Record<string, string>> | string {
  const out: Record<string, Record<string, string>> = {};
  for (const { name, members } of decls) {
    const merged = out[name] ?? (out[name] = {});
    for (const [member, type] of Object.entries(members)) {
      const existing = merged[member];
      if (existing !== undefined && existing !== type) {
        return `Subsequent property declarations must have the same type: ${name}.${member}`;
      }
      merged[member] = type;
    }
  }
  return out;
}

